// Synthetic FITS and end-to-end safety tests. No user files or network calls.
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using System.Threading;

namespace AstroArchive {
 public partial class Tests {
  static int passed,skipped;static string root;static CancellationToken ct=CancellationToken.None;
  static void Check(bool test,string message){if(!test)throw new Exception(message);}
  static void Test(string name,Action action){try{action();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){Console.WriteLine("FAIL "+name+": "+e);Environment.ExitCode=1;}}
  static void Expect(Action action,string message){bool threw=false;try{action();}catch{threw=true;}Check(threw,message);}
  static void WindowsTest(string name,Action action){if(Environment.OSVersion.Platform==PlatformID.Win32NT)Test(name,action);else{skipped++;Console.WriteLine("SKIP (Windows required) "+name);}}
  public static int Main(string[] args){AppContext.SetSwitch("Switch.System.IO.UseLegacyPathHandling",false);AppContext.SetSwitch("Switch.System.IO.BlockLongPaths",false);root=Path.GetFullPath(args.Length>0?args[0]:"test-data");Directory.CreateDirectory(root);Repository.LocalIndexBase=Path.Combine(root,"working-indexes");
   FileSearchTests();ImportPolicyTests();TelescopeTests();PreviewGestureTests();SkyContextTests();FailedFilenameTests();TableCatalogTests();ObservingCityTests();MountLabelTests();TargetNavigationTests();
   Test("Dump imports nested telescope data and preserves failures and metadata",()=>{
    using(var repo=new Repository(Path.Combine(root,"dump-repo"))){repo.EnsureDumpFolder();Check(Directory.Exists(repo.DumpFolder),"Dump folder missing");string directory=Path.Combine(repo.DumpFolder,"DWARF_RAW_TELE_M45_EXP_60_GAIN_60_2026-10-06-21-00-00-000");Directory.CreateDirectory(directory);
     string file=Path.Combine(directory,"raw_001.fit");Write(file,64,48,(x,y)=>1800,LightHeaders(new DateTime(2026,10,6,21,0,0),"M45"));string hash=Util.Hash(file,ct);File.WriteAllText(Path.Combine(directory,"shotsInfo.json"),"{\"targetName\":\"M45\"}");File.WriteAllText(Path.Combine(repo.DumpFolder,"bad.fit"),"not FITS");File.WriteAllText(Path.Combine(repo.DumpFolder,"keep.txt"),"keep");
     var result=repo.ProcessDump(ct,NoProgress);var capture=repo.All().Single();Check(result.Import.Imported==1&&result.Plan.Errors.Count==1&&result.NeedsReview,"Dump counts or errors wrong");Check(capture.Hash==hash&&capture.Target=="M45"&&capture.Telescope=="Unknown"&&!Util.Within(repo.FilePath(capture),repo.DumpFolder),"Dump sorting or unassigned device metadata wrong");Check(File.Exists(Path.Combine(repo.Root,capture.SidecarRelativePath)),"Session metadata not preserved");Check(File.Exists(Path.Combine(repo.DumpFolder,"bad.fit"))&&File.Exists(Path.Combine(repo.DumpFolder,"keep.txt")),"Failed or unsupported drop removed");Check(File.Exists(Path.Combine(directory,"shotsInfo.json")),"Session JSON removed");Check(File.Exists(Path.Combine(repo.Meta,"reports","last-dump.txt")),"Dump report missing");
     if(Environment.OSVersion.Platform==PlatformID.Win32NT)Check(!File.Exists(file)&&result.Import.OriginalsDeleted==1,"Verified dump source not removed");else Check(File.Exists(file)&&result.Import.OriginalsKept==1,"Unsupported cleanup removed source");
     string pending=Path.Combine(repo.DumpFolder,"pending.fit");Write(pending,64,48,(x,y)=>1900,new Dictionary<string,string>());var reindex=repo.Scan(repo.Root,"X","Auto",ct,NoProgress,true);Check(!reindex.Frames.Any(f=>Util.Within(f.SourcePath,repo.DumpFolder)),"Repository reindex indexed pending dump files");
     Expect(()=>repo.Scan(repo.DumpFolder,"X","Auto",ct,NoProgress),"Normal import allowed nested dump source");Expect(()=>repo.Import(new List<Frame>(),ct,NoProgress,new ImportOptions{DumpInbox=true,DeleteOriginals=true,SourceRoot=repo.Root}),"Forged dump root accepted");Expect(()=>SourceCleanup.DeleteDumpVerified(Path.Combine(root,"outside.fit"),repo.FilePath(capture),hash,repo.Root,ct),"Dump cleanup escaped source boundary");
    }
   });
   Test("Dump duplicate cleanup preserves edited archive metadata and recovers missing copies",()=>{
    using(var repo=new Repository(Path.Combine(root,"dump-duplicate-repo"))){repo.EnsureDumpFolder();string file=Path.Combine(repo.DumpFolder,"Light_M45.fit");Write(file,64,48,(x,y)=>1750,LightHeaders(new DateTime(2026,10,6,21,0,0),"M45"));byte[] original=File.ReadAllBytes(file);repo.ProcessDump(ct,NoProgress);var capture=repo.All().Single();capture.Target="M33";capture.Telescope="UserScope";repo.Refile(capture,ct);File.WriteAllBytes(file,original);
     var duplicate=repo.ProcessDump(ct,NoProgress);Check(duplicate.Import.Imported==0&&duplicate.Import.Duplicates==1&&repo.All().Single().Target=="M33"&&repo.All().Single().Telescope=="UserScope","Duplicate replaced archive metadata");if(Environment.OSVersion.Platform==PlatformID.Win32NT)Check(!File.Exists(file)&&duplicate.Import.OriginalsDeleted==1,"Duplicate remained in Dump");else Check(File.Exists(file)&&duplicate.Import.OriginalsKept==1,"Duplicate removed without native verification");
     File.WriteAllBytes(file,original);File.Delete(repo.FilePath(repo.All().Single()));var restore=repo.ProcessDump(ct,NoProgress);Check(restore.Import.Imported==1&&repo.Verify(ct,NoProgress)==0&&repo.All().Single().Target=="M33"&&repo.All().Single().Telescope=="UserScope","Missing archive copy or edited metadata was not restored");
    }
   });
   Test("Canceled dump ingestion retains pending sources",()=>{using(var repo=new Repository(Path.Combine(root,"dump-cancel-repo"))){repo.EnsureDumpFolder();string file=Path.Combine(repo.DumpFolder,"Light_M45.fit");Write(file,64,48,(x,y)=>1700,new Dictionary<string,string>());using(var canceled=new CancellationTokenSource()){canceled.Cancel();Expect(()=>repo.ProcessDump(canceled.Token,NoProgress),"Dump cancellation ignored");}Check(File.Exists(file)&&repo.All().Count==0,"Canceled dump changed sources or index");}});
   WindowsTest("Locked dump sources retry as duplicates after cleanup failure",()=>{using(var repo=new Repository(Path.Combine(root,"dump-lock-repo"))){repo.EnsureDumpFolder();string file=Path.Combine(repo.DumpFolder,"Light_M45.fit");Write(file,64,48,(x,y)=>1700,new Dictionary<string,string>());using(var locked=File.Open(file,FileMode.Open,FileAccess.Read,FileShare.Read)){var result=repo.ProcessDump(ct,NoProgress);Check(result.Import.Imported==1&&result.Import.OriginalsKept==1&&File.Exists(file),"Locked source not retained with verified archive copy");}var retry=repo.ProcessDump(ct,NoProgress);Check(retry.Import.Duplicates==1&&retry.Import.OriginalsDeleted==1&&!File.Exists(file)&&repo.All().Count==1,"Cleanup retry failed");}});
   WindowsTest("Dump cleanup refuses inbox destinations and identical hard links",()=>{using(var repo=new Repository(Path.Combine(root,"dump-hardlink-repo"))){repo.EnsureDumpFolder();string source=Path.Combine(repo.DumpFolder,"source.fit"),copy=Path.Combine(repo.Root,"copy.fit"),inboxCopy=Path.Combine(repo.DumpFolder,"copy.fit");File.WriteAllText(source,"same-file");Check(CreateHardLink(copy,source,IntPtr.Zero),"Test hard link creation failed");Expect(()=>SourceCleanup.DeleteDumpVerified(source,copy,Util.Hash(source,ct),repo.Root,ct),"Same file identity allowed dump deletion");File.Copy(source,inboxCopy);Expect(()=>SourceCleanup.DeleteDumpVerified(source,inboxCopy,Util.Hash(source,ct),repo.Root,ct),"Inbox copy allowed dump deletion");Check(File.Exists(source)&&File.Exists(copy)&&File.Exists(inboxCopy),"Guarded dump cleanup lost a file");}});
   Test("Siril handoff exports only one eligible stack and uses a positional image argument",()=>{
    string source=Path.Combine(root,"siril-source");Directory.CreateDirectory(source);var headers=LightHeaders(new DateTime(2026,10,6,21,0,0),"M45");headers["NCOMBINE"]="12";string file=Path.Combine(source,"Stacked_M45.fit");Write(file,64,48,(x,y)=>1800,headers);string appDir=Path.Combine(root,"Siril app");Directory.CreateDirectory(appDir);string executable=Path.Combine(appDir,"siril.exe");File.WriteAllText(executable,"launch fixture");
    using(var repo=new Repository(Path.Combine(root,"siril-repo"))){repo.Import(repo.Scan(source,"Scope-1","Auto",ct,NoProgress).Frames,ct,NoProgress);var frames=repo.All();Check(SirilHandoff.CanSend(frames),"Stack handoff unavailable");var options=new ExportOptions{Parent=root,Name="Siril working copy Ω"};string image=SirilHandoff.ExportStack(repo,frames,options,executable,ct,NoProgress);var launch=SirilHandoff.LaunchInfo(executable,image);Check(!Util.Within(image,repo.Root)&&Util.Hash(image,ct)==frames[0].Hash&&File.Exists(file),"Handoff did not preserve a verified working copy");Check(launch.FileName==Path.GetFullPath(executable)&&!launch.UseShellExecute&&launch.Arguments=="\""+image+"\""&&launch.WorkingDirectory==Path.GetDirectoryName(image),"Siril GUI launch contract incorrect");
     frames[0].Kind="Light";Check(!SirilHandoff.CanSend(frames),"Single sub offered as stack");Expect(()=>SirilHandoff.ExportStack(repo,frames,new ExportOptions{Parent=root,Name="bad-siril"},executable,ct,NoProgress),"Light handoff accepted");Check(!Directory.Exists(Path.Combine(root,"bad-siril")),"Invalid handoff created export");frames[0].Kind="Stack";frames[0].Rejected=true;Check(!SirilHandoff.CanSend(frames),"Rejected stack accepted");frames[0].Rejected=false;frames[0].OriginalName+=".gz";Check(!SirilHandoff.CanSend(frames),"Compressed stack offered");Check(!SirilHandoff.CanSend(new List<Frame>{frames[0],frames[0]}),"Multiple images offered as a single sequence");Expect(()=>SirilHandoff.ValidateExecutable(Path.Combine(appDir,"siril-cli.exe")),"CLI executable accepted");
    }
   });
