   Test("Seestar target, subs and stack naming",()=>{string dir=Path.Combine(root,"seestar","MyWorks","M 45_sub");Directory.CreateDirectory(dir);string p=Path.Combine(dir,"Light_M_45_10.0s_2026-10-06-23-59-00.fit");Write(p,64,48,(x,y)=>1000+x+y,new Dictionary<string,string>());var f=Classifier.Read(p,Path.Combine(root,"seestar"),"Seestar-01","Seestar S50 Pro");Check(f.Kind=="Light"&&f.Target=="M45","Seestar sub naming");Check(f.Exposure==10,"Exposure naming");string stack=Path.Combine(root,"seestar","Stacked_M45_180x10sec_T7C_2026-10-06-23-59-00.fit");Write(stack,64,48,(x,y)=>2000+x+y,new Dictionary<string,string>());var s=Classifier.Read(stack,Path.Combine(root,"seestar"),"Seestar-01","Seestar S50 Pro");Check(s.Kind=="Stack"&&s.Target=="M45","Stack naming");Check(s.Exposure==10&&s.Temperature==7,"Stack metadata naming");});
   Test("Dwarf raw, raw dark and master calibration conventions",()=>{string baseDir=Path.Combine(root,"dwarf");string dir=Path.Combine(baseDir,"Astronomy","DWARF_RAW_TELE_NGC_6888_EXP_60_GAIN_60_2026-10-06-21-00-00-000");Directory.CreateDirectory(dir);string p=Path.Combine(dir,"raw_tele_NGC6888_2026-10-06-21-00-00-000.fits");Write(p,64,48,(x,y)=>1000+x+y,new Dictionary<string,string>());var f=Classifier.Read(p,baseDir,"Dwarf-03","Auto");Check(f.Target=="NGC6888"&&f.Kind=="Light"&&f.Camera=="Telephoto","Dwarf raw convention");Check(f.Exposure==60&&f.Gain==60,"Dwarf session parameters");string d=Path.Combine(baseDir,"Astronomy","CALI_FRAME","dark","cam_0","dark_exp_60.000000_gain_60_bin_1_10C_stack_10.fits");Directory.CreateDirectory(Path.GetDirectoryName(d));Write(d,64,48,(x,y)=>1000,new Dictionary<string,string>());var dark=Classifier.Read(d,baseDir,"Dwarf-03","Auto");Check(dark.Kind=="Master dark"&&dark.StackCount==10&&dark.Temperature==10,"Master dark convention");string raw=Path.Combine(baseDir,"DWARF_DARK","cam_1","dark_exp_60_gain_60_bin_1_9C_0001.fits");Directory.CreateDirectory(Path.GetDirectoryName(raw));Write(raw,64,48,(x,y)=>1000,new Dictionary<string,string>());var rd=Classifier.Read(raw,baseDir,"Dwarf-03","Auto");Check(rd.Kind=="Dark"&&rd.Camera=="Wide","Raw dark convention");});
   Test("Header precedence, mount evidence and false calibration flag",()=>{string p=Path.Combine(root,"metadata.fit");Write(p,64,48,(x,y)=>1000,new Dictionary<string,string>{{"OBJECT","'M33'"},{"IMAGETYP","'LIGHT'"},{"EXPTIME","30.0"},{"GAIN","70"},{"MOUNTMOD","'EQ'"},{"CALIBRAT","F"}});var f=Classifier.Read(p,root,"Dwarf-03","Dwarf 3");Check(f.Target=="M33"&&f.Exposure==30&&f.Mount=="EQ","Header precedence");Check(f.Calibration=="Unknown","False calibration interpreted as calibrated");});
   Test("Triangle matching: rotation, shift, missing stars and outliers",()=>{var a=Stars(80,1000,700,123);double angle=17.35*Math.PI/180;var b=a.Where((s,i)=>i%7!=0).Select(s=>new Star(Math.Cos(angle)*s.X-Math.Sin(angle)*s.Y+140,Math.Sin(angle)*s.X+Math.Cos(angle)*s.Y-80,s.Flux)).ToList();b.AddRange(Stars(12,1000,700,75));var m=Rotation.Match(a,b,1000,700,ct);Check(Math.Abs(m.Angle-17.35)<0.01,"Wrong recovered angle: "+m.Angle);Check(m.Matches>55&&m.Rms<0.01,"Match quality");});
   Test("Triangle matching rejects reflected or unrelated fields",()=>{var a=Stars(60,1000,700,123);var b=a.Select(s=>new Star(1000-s.X,s.Y,s.Flux)).ToList();Expect(()=>Rotation.Match(a,b,1000,700,ct),"Reflection accepted");Expect(()=>Rotation.Match(a,Stars(60,1000,700,222),1000,700,ct),"Unrelated sky accepted");});
   Test("Star detector recovers PSFs and rejects isolated hot pixels",()=>{var stars=Stars(70,480,320,44);var image=Paint(stars,480,320,0,0,0,3);var found=Rotation.Detect(image);Check(found.Count>=35,"Too few stars: "+found.Count);Check(found.Count<=90,"Hot pixel detections");var b=Paint(stars,480,320,4.7,7,-4,8);var match=Rotation.Match(found,Rotation.Detect(b),480,320,ct);Check(Math.Abs(match.Angle-4.7)<0.08,"PSF rotation: "+match.Angle);});
   Test("Repository scan, deduplication, refile, restore and verification",()=>{string src=Path.Combine(root,"mirror"),repoPath=Path.Combine(root,"repository");Directory.CreateDirectory(src);string p=Path.Combine(src,"Light_M45.fit");Write(p,64,48,(x,y)=>1000+x+y,LightHeaders(new DateTime(2026,10,6,21,0,0),"M45"));File.Copy(p,Path.Combine(src,"renamed.fit"),true);using(var repo=new Repository(repoPath)){var plan=repo.Scan(src,"Seestar-01","Seestar S50 Pro",ct,NoProgress);Check(plan.Frames.Count==2&&plan.Frames.Count(entry=>entry.Status=="New")==1,"Duplicate-in-source");repo.Import(plan.Frames,ct,NoProgress);Check(repo.All().Count==1,"Duplicate imported twice");var again=repo.Scan(src,"Seestar-01","Seestar S50 Pro",ct,NoProgress);string expectedHash=Util.Hash(p,ct);Check(again.Frames.Count==2&&again.Frames.All(entry=>(entry.Status=="Duplicate"||entry.Status=="Duplicate (cached)")&&entry.Hash==expectedHash),"Renamed duplicate not recognized");var f=repo.All().First();f.Target="M33";repo.Refile(f,ct);Check(repo.FilePath(f).Contains("M33")&&File.Exists(repo.FilePath(f)),"Refile failed");File.Delete(repo.FilePath(f));var restore=repo.Scan(src,"Seestar-01","Seestar S50 Pro",ct,NoProgress);Check(restore.Frames.Any(x=>x.Status=="Restore"),"Missing not detected");repo.Import(restore.Frames,ct,NoProgress);Check(repo.Verify(ct,NoProgress)==0,"Restored checksum mismatch");Expect(()=>repo.Scan(repoPath,"X","Auto",ct,NoProgress),"Nested source accepted");using(var c=new CancellationTokenSource()){c.Cancel();Expect(()=>repo.Scan(src,"X","Auto",c.Token,NoProgress),"Cancellation ignored");}}});
   Test("Calibration matching: camera identity, gain, temperature and state",()=>{Frame l=new Frame{Telescope="Seestar-01",Camera="Telephoto",Width=3840,Height=2160,Channels=1,BinX=1,BinY=1,Bayer="RGGB",Calibration="Uncalibrated",Gain=80,Exposure=60,Temperature=10,Filter="Broadband",Night="2026-10-06"};Frame d=l.Clone();d.Kind="Dark";d.Temperature=11;Check(Exporter.MatchesCalibration(l,d),"Valid dark rejected");d.Telescope="Seestar-02";Check(!Exporter.MatchesCalibration(l,d),"Other telescope dark accepted");d.Telescope=l.Telescope;d.Temperature=null;Check(!Exporter.MatchesCalibration(l,d),"Unknown temperature accepted");d.Temperature=11;l.Calibration="Calibrated";Check(!Exporter.MatchesCalibration(l,d),"Double calibration allowed");});
