   Test("Default import keeps originals and records source disposition",()=>{string source=Path.Combine(root,"keep-source");Directory.CreateDirectory(source);string file=Path.Combine(source,"Light_M33.fit");Write(file,64,48,(x,y)=>1600,new Dictionary<string,string>());using(var repo=new Repository(Path.Combine(root,"keep-repo"))){var plan=repo.Scan(source,"Unit-01","Auto",ct,NoProgress);var result=repo.Import(plan.Frames,ct,NoProgress);Check(File.Exists(file)&&result.Imported==1&&result.OriginalsDeleted==0,"Default import removed source");Check(repo.All().First().SourceDisposition=="Original retained","Retention not indexed");var duplicate=repo.Scan(source,"Unit-01","Auto",ct,NoProgress);var empty=repo.Import(duplicate.Frames,ct,NoProgress,new ImportOptions{DeleteOriginals=true,SourceRoot=source});Check(empty.Imported==0&&File.Exists(file),"Known duplicate removed");}});
