   WindowsTest("Native verified cleanup removes only newly imported FITS",()=>{string source=Path.Combine(root,"delete-source");Directory.CreateDirectory(source);string file=Path.Combine(source,"Light_M33.fit"),duplicate=Path.Combine(source,"duplicate.fit"),sidecar=Path.Combine(source,"shotsInfo.json");Write(file,64,48,(x,y)=>2200,new Dictionary<string,string>());File.Copy(file,duplicate);File.WriteAllText(sidecar,"{\"targetName\":\"M33\"}");using(var repo=new Repository(Path.Combine(root,"delete-repo"))){var plan=repo.Scan(source,"Unit-01","Auto",ct,NoProgress);string copied=plan.Frames.Single(f=>f.Status=="New").SourcePath,kept=plan.Frames.Single(f=>f.Status=="Duplicate in source").SourcePath;var result=repo.Import(plan.Frames,ct,NoProgress,new ImportOptions{DeleteOriginals=true,SourceRoot=source});Check(result.OriginalsDeleted==1&&result.OriginalsKept==0,string.Join(";",result.CleanupErrors));Check(!File.Exists(copied)&&File.Exists(kept)&&File.Exists(sidecar),"Duplicate or sidecar removed");var stored=repo.All().Single();Check(Util.Hash(repo.FilePath(stored),ct)==stored.Hash&&stored.SourceDisposition.StartsWith("Original deleted"),"Verified copy/index missing");}});
   WindowsTest("Native cleanup rejects a changed repository copy",()=>{string source=Path.Combine(root,"delete-mismatch-source"),destination=Path.Combine(root,"delete-mismatch-repo");Directory.CreateDirectory(source);Directory.CreateDirectory(destination);string original=Path.Combine(source,"source.fit"),copy=Path.Combine(destination,"copy.fit");File.WriteAllText(original,"source-data");File.WriteAllText(copy,"changed-copy");string expected=Util.Hash(original,ct);Expect(()=>SourceCleanup.DeleteVerified(original,copy,expected,source,destination,ct),"Changed copy allowed deletion");Check(File.Exists(original),"Source removed after mismatch");});
   WindowsTest("Native cleanup rejects a hard link to the repository copy",()=>{string source=Path.Combine(root,"hardlink-source"),destination=Path.Combine(root,"hardlink-repo");Directory.CreateDirectory(source);Directory.CreateDirectory(destination);string original=Path.Combine(source,"source.fit"),copy=Path.Combine(destination,"copy.fit");File.WriteAllText(original,"same-file");Check(CreateHardLink(copy,original,IntPtr.Zero),"Test hard link creation failed");Expect(()=>SourceCleanup.DeleteVerified(original,copy,Util.Hash(original,ct),source,destination,ct),"Same file identity allowed deletion");Check(File.Exists(original)&&File.Exists(copy),"Hard-linked file lost");});
   Test("Fast streaming scan defers hashes and deduplicates during verified copy",()=>{string source=Path.Combine(root,"fast-source");Directory.CreateDirectory(source);string one=Path.Combine(source,"Light_M33.fit"),two=Path.Combine(source,"renamed.fit");Write(one,64,48,(x,y)=>1000,new Dictionary<string,string>{{"OBJECT","'M33'"},{"IMAGETYP","'LIGHT'"}});File.Copy(one,two);using(var repo=new Repository(Path.Combine(root,"fast-repo"))){int emitted=0;var plan=repo.Scan(source,"Unit-01","Auto",ct,NoProgress,false,f=>emitted++,true);Check(emitted==2&&plan.Frames.All(f=>string.IsNullOrEmpty(f.Hash)),"Fast scan read payload hashes or withheld rows");var events=new List<string>();var result=repo.Import(plan.Frames,ct,NoProgress,new ImportOptions{SourceRoot=source,Workers=2,OnFrame=f=>events.Add(f.Status)});Check(result.Imported==1&&result.Duplicates==1&&result.Failed==0,"Copy-time deduplication failed");Check(events.Contains("Copying")&&events.Contains("Imported")&&events.Contains("Duplicate"),"Live import states absent");var stored=repo.All().Single();Check(Util.Hash(repo.FilePath(stored),ct)==stored.Hash,"Combined-copy hash incorrect");}});
   Test("Same filename size and restored modification time do not establish duplicates",()=>{string source=Path.Combine(root,"same-size-source");Directory.CreateDirectory(source);string file=Path.Combine(source,"Light_M33.fit");Write(file,64,48,(x,y)=>1200,new Dictionary<string,string>());using(var repo=new Repository(Path.Combine(root,"same-size-repo"))){var first=repo.Scan(source,"Unit-01","Auto",ct,NoProgress,false,null,true);repo.Import(first.Frames,ct,NoProgress,new ImportOptions{SourceRoot=source});long size=new FileInfo(file).Length;DateTime time=File.GetLastWriteTimeUtc(file);Write(file,64,48,(x,y)=>2400,new Dictionary<string,string>());File.SetLastWriteTimeUtc(file,time);Check(new FileInfo(file).Length==size,"Fixture size changed");var second=repo.Scan(source,"Unit-01","Auto",ct,NoProgress,false,null,true);var result=repo.Import(second.Frames,ct,NoProgress,new ImportOptions{SourceRoot=source});Check(result.Imported==1&&repo.All().Count==2,"Same-size changed contents skipped");}});
   Test("Import isolates one failed source and completes later valid files",()=>{string source=Path.Combine(root,"failure-source");Directory.CreateDirectory(source);string bad=Path.Combine(source,"Light_bad.fit"),good=Path.Combine(source,"Light_M33.fit");Write(bad,64,48,(x,y)=>1000,new Dictionary<string,string>());Write(good,64,48,(x,y)=>2000,new Dictionary<string,string>());using(var repo=new Repository(Path.Combine(root,"failure-repo"))){var plan=repo.Scan(source,"Unit-01","Auto",ct,NoProgress,false,null,true);File.Delete(bad);var result=repo.Import(plan.Frames,ct,NoProgress,new ImportOptions{SourceRoot=source,Workers=2});Check(result.Failed==1&&result.Imported==1&&repo.All().Count==1,"One error aborted the whole batch");Check(result.Errors.Single().Contains(bad)&&result.Errors.Single().Contains("0x"),"Error lacks path/code");Check(File.Exists(good)&&Directory.GetFiles(Path.Combine(repo.Meta,"staging")).Length==0,"Original or staging cleanup incorrect");}});
   Test("Indexed manifest and portable checkpoint survive reopening",()=>{string source=Path.Combine(root,"manifest-source"),destination=Path.Combine(root,"manifest-repo"),working="";Directory.CreateDirectory(source);Write(Path.Combine(source,"Light_M33.fit"),64,48,(x,y)=>1800,new Dictionary<string,string>());using(var repo=new Repository(destination)){var plan=repo.Scan(source,"Unit-01","Auto",ct,NoProgress,false,null,true);repo.Import(plan.Frames,ct,NoProgress,new ImportOptions{SourceRoot=source});working=repo.WorkingIndex;Check(!Util.Within(working,destination)&&File.Exists(Path.Combine(repo.Meta,"index.sqlite")),"Working/portable index placement wrong");using(var database=new Database(working)){var manifest=Util.Deserialize<SourceManifest>(database.Query("SELECT data FROM source_manifest").Single());Check(manifest.Status=="Complete"&&manifest.Source.Size>0&&manifest.Source.Modified>0&&!string.IsNullOrEmpty(manifest.Hash)&&!string.IsNullOrEmpty(manifest.Destination),"Manifest identity/content fields missing");}}using(var repo=new Repository(destination))Check(repo.All().Count==1,"Reopening lost records");using(var portable=new Database(Path.Combine(destination,".astroarchive","index.sqlite")))Check(portable.Query("SELECT hash FROM files").Count==1,"Portable snapshot incomplete");});
   Test("Untrusted metadata cannot enable unchanged-content shortcuts",()=>{var a=new FileStamp{Identity="volume:file",Reliable=true,Size=123,Modified=456,Created=2,Changed=3};var b=Util.Deserialize<FileStamp>(Util.Serialize(a));Check(a.VerifiedUnchanged(b),"Stable trusted identity rejected");b.Identity="other:file";Check(!a.VerifiedUnchanged(b),"Changed identity accepted");b.Identity=a.Identity;b.Reliable=false;Check(!a.VerifiedUnchanged(b),"Unsupported filesystem trusted");b.Reliable=true;b.Attributes=0x400000;Check(!a.VerifiedUnchanged(b),"Offline placeholder trusted");b.Attributes=0;b.Changed++;Check(!a.VerifiedUnchanged(b),"Preserved mtime concealed metadata change");});
