   Test("Adaptive import benchmarks 1 2 4 8 workers and retains its choice",()=>{string source=Path.Combine(root,"workers-source"),template=Path.Combine(root,"workers-template.fit");Directory.CreateDirectory(source);Write(template,512,1024,(x,y)=>1500,new Dictionary<string,string>{{"OBJECT","'M33'"},{"IMAGETYP","'LIGHT'"}});for(int i=0;i<64;i++){string file=Path.Combine(source,"Light_M33_"+i.ToString("000")+".fit");File.Copy(template,file);using(var output=new FileStream(file,FileMode.Open,FileAccess.Write)){output.Position=2880;output.WriteByte((byte)i);}}using(var repo=new Repository(Path.Combine(root,"workers-repo"))){var plan=repo.Scan(source,"Unit-01","Auto",ct,NoProgress,false,null,true);var result=repo.Import(plan.Frames,ct,NoProgress,new ImportOptions{SourceRoot=source,Retune=true});Check(result.Imported==64&&result.Failed==0&&result.Trials.Count>=2&&result.Trials.First().Workers==1&&result.Trials.All(t=>new[]{1,2,4,8}.Contains(t.Workers)),"Pilot did not exercise all worker counts");Check(new[]{1,2,4,8}.Contains(result.Workers)&&result.Trials.All(t=>t.Seconds>0),"Worker selection/timing missing");using(var database=new Database(repo.WorkingIndex))Check(database.Query("SELECT data FROM sessions WHERE id LIKE 'workers150:%'").Single()==result.Workers.ToString(),"Tuning decision not retained");Check(repo.Verify(ct,NoProgress)==0,"Concurrent copy changed bytes");}});
