   Test("DWARF calibration cam folders stay separate and conflicts remain unknown",()=>{string source=Path.Combine(root,"camera-source"),tele=Path.Combine(source,"Astronomy","CALI_FRAME","Dark","cam_0","dark_exp_60_gain_60_bin_2_10C_stack_10.fit"),wide=Path.Combine(source,"Astronomy","CALI_FRAME","Dark","cam_1","dark_exp_60_gain_60_bin_1_10C_stack_10.fit");Directory.CreateDirectory(Path.GetDirectoryName(tele));Directory.CreateDirectory(Path.GetDirectoryName(wide));Write(tele,64,48,(x,y)=>1200,new Dictionary<string,string>());Write(wide,64,48,(x,y)=>1600,new Dictionary<string,string>());var a=Classifier.Read(tele,source,"Dwarf-03","Auto");var b=Classifier.Read(wide,source,"Dwarf-03","Auto");Check(a.Camera=="Telephoto"&&b.Camera=="Wide"&&a.Kind=="Master dark"&&b.Kind=="Master dark","Factory cam folder distinction failed");var light=a.Clone();light.Kind="Light";light.Calibration="Uncalibrated";Check(!Exporter.MatchesCalibration(light,b),"Wide dark supplied to tele lights");Write(wide,64,48,(x,y)=>1600,new Dictionary<string,string>{{"CAMID","'0'"}});Check(Classifier.Read(wide,source,"Dwarf-03","Auto").Camera=="Unknown","Contradictory camera markers guessed");string unknown=Path.Combine(source,"DWARF_DARK","dark_bin_2.fit");Directory.CreateDirectory(Path.GetDirectoryName(unknown));Write(unknown,64,48,(x,y)=>1000,new Dictionary<string,string>());Check(Classifier.Read(unknown,source,"Dwarf-03","Auto").Camera=="Unknown","Binning/dimensions used as camera identity");});
   Test("Export session separation is opt-in for subs and stacks",()=>{string source=Path.Combine(root,"sessions-source");foreach(string session in new[]{"SessionA","SessionB"})Write(Path.Combine(source,session,"Light_M33.fit"),64,48,(x,y)=>session=="SessionA"?1400:1800,LightHeaders(new DateTime(2026,10,6,21,0,0),"M33"));var stack=LightHeaders(new DateTime(2026,10,6,21,0,0),"M33");stack["NCOMBINE"]="10";Write(Path.Combine(source,"SessionA","Stacked_M33.fit"),64,48,(x,y)=>2200,stack);using(var repo=new Repository(Path.Combine(root,"sessions-repo"))){var plan=repo.Scan(source,"Unit-01","Seestar S50",ct,NoProgress);repo.Import(plan.Frames,ct,NoProgress);var merged=Exporter.Create(repo,repo.All(),new ExportOptions{Parent=root,Name="sessions-merged",Mode="Both",IncludeCalibration=false},ct,NoProgress);Check(!Directory.Exists(Path.Combine(merged,"sessions"))&&Directory.GetDirectories(merged,"lights",SearchOption.AllDirectories).Length==1,"Default separates sessions");var separate=Exporter.Create(repo,repo.All(),new ExportOptions{Parent=root,Name="sessions-separated",Mode="Both",IncludeCalibration=false,SeparateSessions=true},ct,NoProgress);Check(Directory.GetDirectories(Path.Combine(separate,"sessions")).Length==2&&Directory.GetDirectories(separate,"lights",SearchOption.AllDirectories).Length==2&&Directory.GetFiles(Path.Combine(separate,"sessions"),"*Stacked_M33.fit",SearchOption.AllDirectories).Length==1&&Directory.GetFiles(separate,"*.fit",SearchOption.AllDirectories).Length==3,"Session export lost or merged files");}});
   Test("Archive reset deletes indexed copies and cache but retains sources and unindexed files",()=>{string source=Path.Combine(root,"reset-source"),destination=Path.Combine(root,"reset-repo");Directory.CreateDirectory(source);string file=Path.Combine(source,"Light_M33.fit");Write(file,64,48,(x,y)=>1900,new Dictionary<string,string>());using(var repo=new Repository(destination)){var plan=repo.Scan(source,"Unit-01","Auto",ct,NoProgress);repo.Import(plan.Frames,ct,NoProgress);repo.CachePut("solve120:test","cached");File.WriteAllText(Path.Combine(destination,"unindexed.txt"),"keep");string copy=repo.FilePath(repo.All().Single());var errors=repo.ResetArchive(ct,NoProgress);Check(errors.Count==0&&!File.Exists(copy)&&File.Exists(file)&&File.Exists(Path.Combine(destination,"unindexed.txt")),"Reset crossed its deletion scope");Check(repo.All().Count==0&&repo.CacheGet("solve120:test")==null,"Reset retained archive data/cache");Check(repo.Deletions().Count==1&&repo.Scan(source,"Unit-01","Auto",ct,NoProgress).Frames.Single().Status=="Deleted","Reset lost deletion exclusions");}});
