  [System.Runtime.InteropServices.DllImport("kernel32.dll",EntryPoint="CreateHardLinkW",CharSet=System.Runtime.InteropServices.CharSet.Unicode,SetLastError=true)]static extern bool CreateHardLink(string link,string existing,IntPtr security);
  static void NoProgress(ProgressInfo p){}
  static Dictionary<string,string> LightHeaders(DateTime t,string target){return new Dictionary<string,string>{{"OBJECT","'"+target+"'"},{"IMAGETYP","'LIGHT'"},{"DATE-OBS","'"+t.ToString("yyyy-MM-ddTHH:mm:ss",CultureInfo.InvariantCulture)+"'"},{"EXPTIME","60"},{"GAIN","80"},{"CCD-TEMP","10"},{"CAMID","'0'"},{"OBJCTRA","'03:47:00'"},{"OBJCTDEC","'+24:07:00'"}};}
  static List<Star> Stars(int n,int w,int h,int seed){var random=new Random(seed);var a=new List<Star>();for(int i=0;i<n;i++)a.Add(new Star(20+random.NextDouble()*(w-40),20+random.NextDouble()*(h-40),2500+random.NextDouble()*10000));return a;}
  static FitsImage Paint(List<Star> stars,int w,int h,double degrees,double dx,double dy,int seed){var r=new Random(seed);var p=new double[w*h];for(int i=0;i<p.Length;i++)p[i]=900+0.04*(i%w)+0.03*(i/w)+(r.NextDouble()-0.5)*30;double a=degrees*Math.PI/180;
   foreach(var star in stars){double xx=star.X-w/2,yy=star.Y-h/2;double x=Math.Cos(a)*xx-Math.Sin(a)*yy+w/2+dx,y=Math.Sin(a)*xx+Math.Cos(a)*yy+h/2+dy;for(int j=Math.Max(0,(int)y-5);j<Math.Min(h,(int)y+6);j++)for(int k=Math.Max(0,(int)x-5);k<Math.Min(w,(int)x+6);k++)p[j*w+k]+=star.Flux*Math.Exp(-((k-x)*(k-x)+(j-y)*(j-y))/2.4);}
   for(int k=0;k<12;k++)p[r.Next(p.Length)]=40000;return new FitsImage{Pixels=p,Width=w,Height=h};}
  static void Series(bool stable,bool geometry){string tag=stable?(geometry?"eq":"unknown"):"az",src=Path.Combine(root,"series-"+tag);Directory.CreateDirectory(src);var stars=Stars(90,480,320,86);for(int i=0;i<9;i++){var image=Paint(stars,480,320,stable?0:i*0.35,i*0.3,-i*0.2,100+i);var head=LightHeaders(new DateTime(2026,10,6,0,0,0).AddMinutes(i*4),"M45");if(!geometry){head.Remove("OBJCTRA");head.Remove("OBJCTDEC");}Write(Path.Combine(src,"Light_"+i.ToString("000")+".fit"),960,640,(x,y)=>image.Pixels[(y/2)*480+x/2],head);}
   using(var repo=new Repository(Path.Combine(root,"series-repo-"+tag))){var p=repo.Scan(src,"Seestar-01","Seestar S50 Pro",ct,NoProgress);repo.Import(p.Frames,ct,NoProgress);var result=Rotation.Analyze(repo,repo.All(),geometry?(double?)51.5:null,geometry?(double?)0:null,ct,NoProgress);if(stable&&geometry)Check(result.Mount=="EQ?",result.Evidence);else if(stable)Check(result.Mount=="Unknown",result.Evidence);else Check(result.Mount=="Alt-Az?",result.Evidence);Check(result.Points.Count>=6,"Too few series matches");Console.WriteLine("  "+result.Mount+"; "+result.DriftDegrees.ToString("0.000")+"°; "+result.Points.Count+" frames");}
  }
  static string Card(string k,string v){return (k.PadRight(8)+"= "+v).PadRight(80).Substring(0,80);}
  static void Header(Stream s,List<string> cards){string t=string.Concat(cards)+"END".PadRight(80);t=t.PadRight((t.Length+2879)/2880*2880);byte[] b=Encoding.ASCII.GetBytes(t);s.Write(b,0,b.Length);}
  static void Write(string path,int w,int h,Func<int,int,double> value,Dictionary<string,string> extra,bool extension=false){Directory.CreateDirectory(Path.GetDirectoryName(path));using(var s=File.Create(path)){
   if(extension){var primary=new List<string>{Card("SIMPLE","T"),Card("BITPIX","8"),Card("NAXIS","0"),Card("EXTEND","T")};primary.AddRange(extra.Select(kv=>Card(kv.Key,kv.Value)));Header(s,primary);}
   var cards=new List<string>{Card(extension?"XTENSION":"SIMPLE",extension?"'IMAGE'":"T"),Card("BITPIX","16"),Card("NAXIS","2"),Card("NAXIS1",w.ToString()),Card("NAXIS2",h.ToString()),Card("BSCALE","1"),Card("BZERO","32768")};if(extension){cards.Add(Card("PCOUNT","0"));cards.Add(Card("GCOUNT","1"));}else cards.AddRange(extra.Select(kv=>Card(kv.Key,kv.Value)));Header(s,cards);
   for(int y=0;y<h;y++)for(int x=0;x<w;x++){int v=(int)Math.Max(0,Math.Min(65535,value(x,y)))-32768;short n=(short)v;s.WriteByte((byte)(n>>8));s.WriteByte((byte)n);}while(s.Length%2880!=0)s.WriteByte(0);
  }}
  static void WriteFloat(string path,int w,int h,int channels){using(var s=File.Create(path)){Header(s,new List<string>{Card("SIMPLE","T"),Card("BITPIX","-32"),Card("NAXIS","3"),Card("NAXIS1",w.ToString()),Card("NAXIS2",h.ToString()),Card("NAXIS3",channels.ToString())});for(int c=0;c<channels;c++)for(int y=0;y<h;y++)for(int x=0;x<w;x++){byte[] b=BitConverter.GetBytes((float)(10*(c+1)));Array.Reverse(b);s.Write(b,0,b.Length);}while(s.Length%2880!=0)s.WriteByte(0);}}
 }
}
